import java.util.*;

class Solution {
    public List<Integer> levelOrder(TreeNode root) {
        List<Integer> answer = new ArrayList<>();
        walk(root, answer);
        return answer;
    }

    private void walk(TreeNode node, List<Integer> answer) {
        if (node == null) {
            return;
        }
        answer.add(node.val);
        walk(node.left, answer);
        walk(node.right, answer);
    }
}
